  "module": "src/index.ts",
  "type": "module",
  "license": "MIT",
  "author": "DotBlood",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DotBlood/opencodeignore-v2.git"
  },
  "bugs": {
    "url": "https://github.com/DotBlood/opencodeignore-v2/issues"
  },
  "homepage": "https://github.com/DotBlood/opencodeignore-v2",
  "publishConfig": {
    "access": "public"
  },
  "keywords": ["opencode", "opencode-plugin", "agentignore"],
